  let flashDeck=[],flashIndex=0,flashRevealed=false,spellingDeck=[],spellingIndex=0,spellingSolved=false,spellingHadError=false,spellingRecorded=false,quiz=null,grammarQuiz=null,pendingImport=null,pendingVocabImport=null,draftTimer=null,wrongNoteTimer=null,writingTimerId=null,writingSeconds=0,writingVersionOf='',activeWritingPromptId='',installPrompt=null,lastPracticeConfig=null,practicePaused=false,practiceTimerId=null,reviewSession=null,lastCompletedPracticeId=null,currentVocabMode='list',wordPage=1,questionPage=1,flashTouchStart=0;
  const WORD_PAGE_SIZE=100,QUESTION_PAGE_SIZE=50;
