  const todayKey=()=>localKey(new Date());
  const formatDate=value=>new Intl.DateTimeFormat('zh-CN',{month:'short',day:'numeric'}).format(value instanceof Date?value:new Date(value));
  const formatFullDate=value=>new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'short'}).format(value instanceof Date?value:new Date(value));
  const clamp=(n,min,max)=>Math.min(max,Math.max(min,n));
  const profile=()=>state.studyProfile||{targetLevel:'6',examDate:'',dailyWordTarget:10,dailyGrammarTarget:2,dailyQuestionTarget:10};
  const anniversaries=[{name:'小雨生日',mode:'countdown',month:7,day:31,icon:'🎂'},{name:'和小雨在一起',mode:'elapsed',year:2025,month:8,day:17,icon:'♥'}];

  function toast(message){const element=$('#toast');element.textContent=message;element.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>element.classList.remove('show'),2800)}
  function save(render=true){const result=Store.save(state);state=result.data;if(!result.ok){toast('保存失败：请立即导出备份。');return false}if(result.compacted&&!sessionStorage.getItem('topik-storage-slimmed')){sessionStorage.setItem('topik-storage-slimmed','1');toast('本地空间不足，已自动压缩旧练习流水并保存。')}if(render)renderAll();return true}
  function completeDailyTask(task){const key=todayKey(),done=state.daily[key]||[];if(!done.includes(task))state.daily[key]=[...done,task]}
  function recordActivity(type,amount=1){state.activityLog.push({id:Store.newId('activity'),type,amount,date:new Date().toISOString()});if(state.activityLog.length>5000)state.activityLog=state.activityLog.slice(-5000);const todayAmount=state.activityLog.filter(item=>item.type===type&&localKey(item.date)===todayKey()).reduce((sum,item)=>sum+item.amount,0);if(type==='grammar'&&todayAmount>=profile().dailyGrammarTarget)completeDailyTask('grammar');if(type==='practice'&&todayAmount>=profile().dailyQuestionTarget)completeDailyTask('practice');if(type==='writing')completeDailyTask('writing')}
  function openDialog(id){const dialog=$(`#${id}`);if(dialog&&!dialog.open)dialog.showModal()}
  function closeDialog(id){const dialog=$(`#${id}`);if(dialog?.open)dialog.close()}
  function isStandalone(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}
  function setupInstall(){const button=$('#installAppButton');if(!button||isStandalone())return;button.hidden=false;const iOS=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);$('#installInstructions').textContent=iOS?'在 Safari 底部或顶部点击“分享”图标，然后选择“添加到主屏幕”，最后点击“添加”。':'点击“立即安装”；如果按钮不可用，请打开浏览器菜单并选择“安装应用”或“添加到主屏幕”。';$('#installNowButton').hidden=!installPrompt}
