  function showUpdateBanner(message='刷新后即可使用最新功能。'){const banner=$('#updateBanner');if(!banner)return;$('#updateMessage').textContent=message;banner.hidden=false}
  async function checkForUpdate(manual=false){if(!APP_VERSION||location.protocol==='file:'){if(manual)toast('本地文件模式无法检查线上版本。');return false}try{const response=await fetch(`version.json?ts=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const latest=await response.json(),version=String(latest.version||'');if(version&&version!==APP_VERSION){showUpdateBanner(`当前版本 ${APP_VERSION} · 最新版本 ${version}，刷新后生效。`);return true}if(manual)toast(`当前已是最新版本：${APP_VERSION}`);return false}catch(error){if(manual)toast(`检查更新失败：${error.message}`);return false}}
  function registerServiceWorker(){if(!('serviceWorker' in navigator)||!location.protocol.startsWith('http'))return;navigator.serviceWorker.register('sw.js?v=20260819-5').then(registration=>{if(registration.waiting)showUpdateBanner('新版离线缓存已准备好，刷新后生效。');registration.addEventListener('updatefound',()=>{const worker=registration.installing;if(!worker)return;worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)showUpdateBanner('新版离线缓存已准备好，刷新后生效。')})})}).catch(error=>console.warn('Service worker registration failed',error))}
  function setupAutoUpdate(){const reload=$('#updateReloadButton'),later=$('#updateLaterButton'),banner=$('#updateBanner');reload?.addEventListener('click',()=>location.reload());later?.addEventListener('click',()=>{if(banner)banner.hidden=true});checkForUpdate();setInterval(checkForUpdate,30*60*1000)}
  window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;setupInstall()});window.addEventListener('appinstalled',()=>{$('#installAppButton').hidden=true;closeDialog('installDialog');toast('TOPIK Study 已安装到桌面。')});

  function showPage(id,updateHash=true){if(!document.getElementById(id))id='today';if($('.page.active')?.id==='writing'&&id!=='writing'&&activeWritingPromptId)saveDraft();$$('.page').forEach(page=>page.classList.toggle('active',page.id===id));$$('[data-page]').forEach(button=>button.classList.toggle('active',button.dataset.page===id));if(updateHash&&location.hash!==`#${id}`)history.replaceState(null,'',`#${id}`);window.scrollTo({top:0,behavior:updateHash?'smooth':'auto'});if(id==='progressPage')renderProgress();if(id==='vocabulary'&&!flashDeck.length)resetFlashcards()}
  function bindNavigation(){$$('[data-page]').forEach(button=>button.addEventListener('click',()=>showPage(button.dataset.page)));window.addEventListener('hashchange',()=>showPage(location.hash.slice(1),false))}

  function studyDates(){const dates=new Set();Object.entries(state.daily).forEach(([date,tasks])=>{if(tasks.length)dates.add(date)});state.activityLog.forEach(item=>dates.add(localKey(item.date)));state.writings.forEach(item=>dates.add(localKey(item.date)));state.quizHistory.forEach(item=>dates.add(localKey(item.date)));state.testRecords.forEach(item=>{if(item.completedAt)dates.add(localKey(item.completedAt))});state.fullMockHistory.forEach(item=>{if(item.completedAt)dates.add(localKey(item.completedAt))});return dates}
  function streakDays(){const dates=studyDates();let cursor=new Date();cursor.setHours(12,0,0,0);if(!dates.has(localKey(cursor)))cursor.setDate(cursor.getDate()-1);let count=0;while(dates.has(localKey(cursor))){count++;cursor.setDate(cursor.getDate()-1)}return count}

  function questionPerformance(section='reading'){const map=new Map();state.practiceRecords.filter(record=>record.section===section).forEach(record=>record.answers.forEach(answer=>{const question=state.questionBank.find(item=>item.id===answer.questionId),category=question?.related||'未分类';if(!question)return;const item=map.get(category)||{category,total:0,correct:0};item.total++;if(answer.correct)item.correct++;map.set(category,item)}));return [...map.values()].map(item=>({...item,accuracy:Math.round(item.correct/item.total*100)})).sort((a,b)=>a.accuracy-b.accuracy||b.total-a.total)}
  function currentWeakness(section='reading'){const performance=questionPerformance(section);return performance.find(item=>item.total>=2)||performance[0]||null}
  function bookmarkedQuestions(section=''){const ids=new Set(state.questionBookmarks||[]);return state.questionBank.filter(question=>ids.has(question.id)&&(!section||question.section===section))}
  const wrongReasonLabels={unknown:'未标记',vocabulary:'词汇不熟',grammar:'语法不清',careless:'粗心误选',time:'时间不足'};
  function wrongIsDue(item){return !item.mastered&&(!item.nextReviewAt||new Date(item.nextReviewAt)<=new Date())}
  function activeWrongQuestions(section='',dueOnly=false){const ids=new Set(state.wrongAnswers.filter(item=>!item.mastered&&(!dueOnly||wrongIsDue(item))).map(item=>item.questionId));return state.questionBank.filter(question=>ids.has(question.id)&&(!section||question.section===section))}
  function elapsedCalendar(start,today){const totalDays=Math.max(0,Math.round((today-start)/86400000));let years=today.getFullYear()-start.getFullYear(),yearCursor=new Date(start);yearCursor.setFullYear(start.getFullYear()+years);if(yearCursor>today){years--;yearCursor=new Date(start);yearCursor.setFullYear(start.getFullYear()+years)}let months=(today.getFullYear()-yearCursor.getFullYear())*12+today.getMonth()-yearCursor.getMonth(),monthCursor=new Date(yearCursor);monthCursor.setMonth(yearCursor.getMonth()+months);if(monthCursor>today){months--;monthCursor=new Date(yearCursor);monthCursor.setMonth(yearCursor.getMonth()+months)}const days=Math.max(0,Math.round((today-monthCursor)/86400000));return {totalDays,years,months,days}}
  function renderAnniversaries(){const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate(),12);$('#anniversaryCountdown').innerHTML=anniversaries.map(item=>{if(item.mode==='elapsed'){const start=new Date(item.year,item.month-1,item.day,12),elapsed=elapsedCalendar(start,today);return `<article class="anniversary-card elapsed"><span class="anniversary-icon">${item.icon}</span><span class="anniversary-copy"><strong>${item.name}</strong><small>从 ${item.year} 年 ${item.month} 月 ${item.day} 日开始 · ${elapsed.years} 年 ${elapsed.months} 个月 ${elapsed.days} 天</small></span><span class="anniversary-days"><strong>${elapsed.totalDays}</strong><small>共同走过的天数</small></span></article>`}let target=new Date(today.getFullYear(),item.month-1,item.day,12);if(target<today)target=new Date(today.getFullYear()+1,item.month-1,item.day,12);const days=Math.round((target-today)/86400000);return `<article class="anniversary-card next ${days===0?'today':''}"><span class="anniversary-icon">${item.icon}</span><span class="anniversary-copy"><strong>${item.name}</strong><small>每年 ${item.month} 月 ${item.day} 日 · 下次 ${target.getFullYear()} 年</small></span><span class="anniversary-days"><strong>${days===0?'就是今天':days}</strong><small>${days===0?'好好纪念':'天后'}</small></span></article>`}).join('')}
  function dailyTasks(){const plan=profile();return [['vocabulary','가','复习单词',`完成今日 ${plan.dailyWordTarget} 个单词`],['grammar','文','复习语法',`复习 ${plan.dailyGrammarTarget} 个语法点`],['practice','▤','阅读训练',`完成 ${plan.dailyQuestionTarget} 道阅读题`],['writing','✎','写作练习','完成一篇短文']]}
  function renderToday(){const tasks=dailyTasks(),done=state.daily[todayKey()]||[],percent=Math.round(done.filter(item=>tasks.some(task=>task[0]===item)).length/tasks.length*100),streak=streakDays(),due=dueWords().length,plan=profile(),weak=currentWeakness(),activeWrong=activeWrongQuestions().length,bookmarks=bookmarkedQuestions().length;$('#todayCount').textContent=`${done.filter(item=>tasks.some(task=>task[0]===item)).length} / ${tasks.length} 完成`;$('#todayMessage').textContent=done.length>=tasks.length?'今天的计划已经完成，做得很好。':due?`今天有 ${due} 个到期单词，先从复习开始。`:'完成今天的小目标，保持学习节奏。';$('#todayRing').style.setProperty('--value',percent);$('#todayRing span').textContent=`${percent}%`;$('#headerStreak').textContent=streak;let goal=`目标 TOPIK ${plan.targetLevel}级`;if(plan.examDate){const days=Math.ceil((new Date(`${plan.examDate}T12:00:00`)-new Date())/86400000);goal+=days>=0?` · 距考试 ${days} 天`:' · 考试日期已过'}$('#goalSummary').textContent=goal;$('#taskList').innerHTML=tasks.map(task=>`<article class="task-card ${done.includes(task[0])?'done':''}"><span class="task-icon">${task[1]}</span><span class="task-copy"><strong>${task[2]}</strong><small>${task[3]}</small></span><button class="task-start" data-task-start="${task[0]}">开始</button><input class="check" type="checkbox" data-task="${task[0]}" ${done.includes(task[0])?'checked':''} aria-label="标记${task[2]}已完成"></article>`).join('');const recommendation=state.activePractice?['继续上次真题',`第 ${state.activePractice.examNumber} 届 · 已答 ${state.activePractice.answers.length}/${state.activePractice.questionIds.length}`,'continue']:due?['记忆到期提醒',`${due} 个单词已到复习时间`,'vocab']:bookmarks?['复习收藏难题',`${bookmarks} 道收藏题等待再次确认`,'bookmark']:activeWrong?['优先清理错题',`还有 ${activeWrong} 道阅读/听力错题待掌握`,'wrong']:weak?['今日专项建议',`${weak.category} · 当前正确率 ${weak.accuracy}%`,'weak']:['建立基线成绩','先完成一套 10 题阅读小测','mini'];$('#smartRecommendation').innerHTML=`<div><span class="eyebrow">SMART NEXT STEP</span><strong>${recommendation[0]}</strong><span>${recommendation[1]}</span></div><button class="primary" data-smart-action="${recommendation[2]}">现在开始</button>`;const cards=[['가','已掌握单词',state.words.filter(x=>x.mastered).length,`共 ${state.words.length} 个`],['⏱','今日到期',due,'个单词'],['文','已复习语法',state.grammar.filter(x=>x.reviewed).length,`共 ${state.grammar.length} 个`]];$('#todayStats').innerHTML=cards.map(statCard).join('');$('#startTodayVocab').textContent=`开始今日 ${plan.dailyWordTarget} 词`;renderDailySprint();renderAnniversaries()}
  function toggleTask(task){const key=todayKey(),done=state.daily[key]||[];if(done.includes(task))state.daily[key]=done.filter(x=>x!==task);else{state.daily[key]=[...done,task];recordActivity('daily')}save()}
  function startDailyTask(task){if(task==='vocabulary'){showPage('vocabulary');$('#vocabReviewScope').value='today';setVocabMode('flashcards')}else if(task==='grammar'){showPage('grammar');openGrammarQuiz()}else if(task==='practice'){showPage('papers');setPaperMode('practice');showPracticeSetup();$('#practiceSectionSelect').value='reading';$('#practiceScopeSelect').value='mini';renderPracticeSelectors()}else if(task==='writing')showPage('writing')}
  function smartAction(action){if(action==='vocab')return startDailyTask('vocabulary');showPage('papers');setPaperMode('practice');if(action==='continue'&&state.activePractice){practicePaused=true;renderPracticeSelectors();return beginPractice()}showPracticeSetup();if(action==='wrong'||action==='bookmark'){const questions=action==='wrong'?activeWrongQuestions():bookmarkedQuestions(),section=questions[0]?.section||'reading';$('#practiceSectionSelect').value=section;renderPracticeSelectors();$('#practiceScopeSelect').value=action}else if(action==='weak'){const weak=currentWeakness();$('#practiceSectionSelect').value='reading';renderPracticeSelectors();$('#practiceScopeSelect').value='category';updatePracticeScopeUI();if(weak&&[...$('#practiceCategorySelect').options].some(option=>option.value===weak.category))$('#practiceCategorySelect').value=weak.category}else{$('#practiceSectionSelect').value='reading';renderPracticeSelectors();$('#practiceScopeSelect').value='mini'}updatePracticeScopeUI()}
  function renderDailySprint(){const dueVocab=dueWords().length,dueGrammar=dueGrammarPoints().length,dueWrong=activeWrongQuestions('',true).length,weak=currentWeakness(),writingCount=state.writings.filter(item=>localKey(item.date)===todayKey()).length;const items=[{icon:'가',title:'到期单词',count:dueVocab,detail:dueVocab?`优先复习 ${Math.min(dueVocab,profile().dailyWordTarget)} 个`:'暂无到期，随机巩固 10 个',action:'vocab'},{icon:'文',title:'语法回忆',count:dueGrammar,detail:dueGrammar?`今日到期 ${dueGrammar} 个语法点`:'从错语法/随机语法开始',action:'grammar'},{icon:'✦',title:'错题清理',count:dueWrong,detail:dueWrong?`到期错题 ${dueWrong} 道`:'打开错题本检查待掌握题',action:'wrongDue'},{icon:'▤',title:'薄弱专项',count:weak?`${weak.accuracy}%`:'10题',detail:weak?`${weak.category} · 已做 ${weak.total} 题`:'先做一组阅读小测建立基线',action:weak?'weak':'mini'},{icon:'✎',title:'写作保温',count:writingCount,detail:writingCount?'今天已有写作记录':'写一段 51–54 题短练',action:'writing'}];$('#dailySprint').innerHTML=items.map(item=>`<button class="sprint-card" data-sprint-action="${item.action}"><span class="sprint-icon">${item.icon}</span><span><strong>${item.title}</strong><small>${esc(item.detail)}</small></span><em>${item.count}</em></button>`).join('')}
  function sprintAction(action){if(action==='grammar')return startDailyTask('grammar');if(action==='writing')return startDailyTask('writing');if(action==='wrongDue'){showPage('papers');setPaperMode('wrong');$('#wrongFilter').value='due';renderWrongQuestions();return}if(action==='weak'||action==='mini')return smartAction(action);return startDailyTask('vocabulary')}
  function statCard(item){return `<article class="stat-card"><span class="stat-icon">${item[0]}</span><div><span>${item[1]}</span><strong>${item[2]}</strong><small>${item[3]}</small></div></article>`}

  function dueWords(){const now=new Date();return state.words.filter(word=>word.nextReviewAt&&new Date(word.nextReviewAt)<=now)}
  function wordCategory(){return $('#wordCategoryFilter')?.value||'all'}
  function wordLevel(){return $('#wordLevelFilter')?.value||'all'}
  function inWordCategory(word,category=wordCategory()){return category==='all'||word.category===category}
  function inWordLevel(word,level=wordLevel()){return level==='all'||word.topikLevel===level}
  function inWordFilters(word,category=wordCategory(),level=wordLevel()){return inWordCategory(word,category)&&inWordLevel(word,level)}
  function renderWordCategoryFilter(){const select=$('#wordCategoryFilter');if(!select)return;const current=select.value||'all',categories=[...new Set(state.words.map(word=>word.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-Hans-CN'));select.innerHTML='<option value="all">全部分类</option>'+categories.map(category=>`<option value="${esc(category)}">${esc(category)}</option>`).join('');select.value=categories.includes(current)?current:'all'}
  function renderWordLevelFilter(){const select=$('#wordLevelFilter');if(!select)return;const current=select.value||'all',levels=[...new Set(state.words.map(word=>word.topikLevel).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-Hans-CN',{numeric:true}));select.innerHTML='<option value="all">全部等级</option>'+levels.map(level=>`<option value="${esc(level)}">${esc(level)}</option>`).join('');select.value=levels.includes(current)?current:'all'}
  function reviewWords(scope=$('#vocabReviewScope').value){const base=state.words.filter(word=>inWordFilters(word)),due=dueWords().filter(word=>inWordFilters(word)),unmastered=base.filter(word=>!word.mastered),target=profile().dailyWordTarget;if(scope==='wrong')return base.filter(word=>word.wrongCount>0&&!word.mastered);if(scope==='all')return [...base];if(scope==='random')return shuffle(base).slice(0,Math.min(50,base.length));if(scope==='today'){const dueIds=new Set(due.map(item=>item.id)),unseen=unmastered.filter(word=>!word.lastReviewedAt&&!dueIds.has(word.id));return [...due.slice(0,target),...unseen.slice(0,Math.max(0,target-due.length))]}return unmastered}
  function scheduleWord(word,rating){const now=new Date(),previous=Math.max(0,Number(word.intervalDays)||0),ease=clamp(Number(word.easeFactor)||2.5,1.3,3),next=new Date(now);word.lastResult=rating;word.lastReviewedAt=now.toISOString();word.reviewCount=(word.reviewCount||0)+1;if(rating==='again'){word.successStreak=0;word.easeFactor=clamp(ease-.2,1.3,3);word.intervalDays=0;word.learningState='learning';word.mastered=false;word.wrongCount=(word.wrongCount||0)+1;word.lastWrongAt=now.toISOString();next.setMinutes(next.getMinutes()+10)}else if(rating==='hard'){word.successStreak=Math.max(1,(word.successStreak||0)+1);word.easeFactor=clamp(ease-.15,1.3,3);word.intervalDays=Math.max(1,Math.round(previous?previous*1.2:1));word.learningState='review';next.setDate(next.getDate()+word.intervalDays)}else if(rating==='easy'){word.successStreak=(word.successStreak||0)+2;word.easeFactor=clamp(ease+.15,1.3,3);word.intervalDays=Math.max(4,Math.round(previous?previous*word.easeFactor*1.3:4));word.learningState=word.successStreak>=3?'mastered':'review';word.mastered=word.successStreak>=3;word.wrongCount=0;word.lastWrongAt=null;next.setDate(next.getDate()+word.intervalDays)}else{word.successStreak=(word.successStreak||0)+1;word.easeFactor=ease;word.intervalDays=word.successStreak===1?1:word.successStreak===2?3:Math.max(7,Math.round(Math.max(1,previous)*ease));word.learningState=word.successStreak>=3?'mastered':'review';word.mastered=word.successStreak>=3;if(word.mastered){word.wrongCount=0;word.lastWrongAt=null}next.setDate(next.getDate()+word.intervalDays)}word.nextReviewAt=next.toISOString()}
  function recordVocabAttempt(word,mode,rating){const correct=rating!=='again',now=new Date();state.vocabAttempts.push({id:Store.newId('vocab-attempt'),wordId:word.id,mode,correct,rating,date:now.toISOString()});if(state.vocabAttempts.length>20000)state.vocabAttempts=state.vocabAttempts.slice(-20000);scheduleWord(word,rating);recordActivity('vocabulary');const reviewedToday=new Set(state.vocabAttempts.filter(item=>localKey(item.date)===todayKey()).map(item=>item.wordId)).size;if(reviewedToday>=profile().dailyWordTarget)completeDailyTask('vocabulary')}
  function speakKorean(text){if(!('speechSynthesis' in window))return toast('当前浏览器不支持语音朗读。');speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='ko-KR';utterance.rate=.88;const voice=speechSynthesis.getVoices().find(item=>item.lang?.toLowerCase().startsWith('ko'));if(voice)utterance.voice=voice;speechSynthesis.speak(utterance)}
  function markWordMastered(word){const next=new Date();next.setDate(next.getDate()+30);word.mastered=true;word.learningState='mastered';word.successStreak=Math.max(3,word.successStreak||0);word.intervalDays=Math.max(30,word.intervalDays||0);word.wrongCount=0;word.lastWrongAt=null;word.nextReviewAt=next.toISOString();word.lastResult='easy'}
