  function parseCsv(content){const rows=[],row=[];let field='',quoted=false;const text=content.replace(/^\uFEFF/,'');for(let index=0;index<text.length;index++){const char=text[index];if(quoted){if(char==='"'&&text[index+1]==='"'){field+='"';index++}else if(char==='"')quoted=false;else field+=char}else if(char==='"')quoted=true;else if(char===','){row.push(field);field=''}else if(char==='\n'){row.push(field);rows.push([...row]);row.length=0;field=''}else if(char!=='\r')field+=char}if(field||row.length){row.push(field);rows.push(row)}return rows}
