  function confirmVocabImport(){if(!pendingVocabImport)return;const previous=state,mode=$('input[name="vocabImportMode"]:checked')?.value||'merge';Store.download(state,'topik-study-before-vocabulary-import');state={...state,words:mode==='merge'?mergeVocabulary(state.words,pendingVocabImport.words):pendingVocabImport.words};if(mode==='replace')state.vocabAttempts=[];if(!save(false)){state=previous;toast('词库过大，当前浏览器 localStorage 无法保存。请缩小文件后重试。');return}const count=pendingVocabImport.words.length;pendingVocabImport=null;$('#vocabImportFile').value='';closeDialog('vocabImportDialog');wordPage=1;resetStudyDecks();renderAll();toast(`已${mode==='merge'?'合并':'导入'} ${count} 个词条。`)}

  function renderGrammar(){
    const query=$('#grammarSearch').value.trim().toLowerCase(),filter=$('#grammarFilter').value,level=$('#grammarLevelFilter').value,now=new Date();
    const matches=item=>filter==='all'||filter==='reviewed'&&item.reviewed||filter==='learning'&&!item.reviewed||filter==='wrong'&&item.wrongCount>0||filter==='due'&&item.nextReviewAt&&new Date(item.nextReviewAt)<=now,items=state.grammar.filter(item=>(item.pattern+' '+item.explanation+' '+item.examples+' '+item.level+' '+item.category).toLowerCase().includes(query)).filter(item=>level==='all'||(level==='自定义'?item.category==='自定义':item.level===level)).filter(matches);
    $('#grammarSummary').textContent=`已复习 ${state.grammar.filter(x=>x.reviewed).length} / ${state.grammar.length} 个 · 错语法 ${state.grammar.filter(x=>x.wrongCount>0).length} 个`;
    $('#grammarList').innerHTML=items.length?items.map(item=>`<article class="grammar-card ${item.wrongCount?'needs-review':''}"><div class="item-head"><input class="check" type="checkbox" data-grammar-action="review" data-id="${esc(item.id)}" ${item.reviewed?'checked':''} aria-label="标记 ${esc(item.pattern)} 已复习"><div class="item-copy"><h3>${esc(item.pattern)}</h3><p class="meaning">${esc(item.explanation)}</p>${item.level||item.category?`<div class="word-tags">${item.level?`<span class="word-tag">${esc(item.level)}</span>`:''}${item.category?`<span class="word-tag">${esc(item.category)}</span>`:''}</div>`:''}</div><div class="item-actions"><button data-grammar-action="edit" data-id="${esc(item.id)}">编辑</button><button data-grammar-action="delete" data-id="${esc(item.id)}">删除</button></div></div>${item.examples?`<p class="item-example">${esc(item.examples)}</p>`:''}<div class="record-summary"><span class="status-chip ${item.reviewed?'completed':item.wrongCount?'in_progress':''}">${item.wrongCount?`错 ${item.wrongCount} 次`:item.reviewed?'已复习':'待复习'}</span><span>复习 ${item.reviewCount} 次</span>${item.nextReviewAt?`<span>下次 ${formatDate(item.nextReviewAt)}</span>`:item.lastReviewedAt?`<span>最近 ${formatDate(item.lastReviewedAt)}</span>`:''}</div></article>`).join(''):'<div class="empty">没有找到符合条件的语法。</div>';
  }
  function resetGrammarFilters(){const search=$('#grammarSearch');if(search)search.value='';$('#grammarLevelFilter').value='all';$('#grammarFilter').value='all';renderGrammar();toast('语法筛选已重置。')}
  function openGrammar(id=''){const point=state.grammar.find(x=>x.id===id);$('#grammarDialogTitle').textContent=point?'编辑语法':'添加语法';$('#grammarId').value=point?.id||'';$('#grammarPattern').value=point?.pattern||'';$('#grammarExplanation').value=point?.explanation||'';$('#grammarExamples').value=point?.examples||'';openDialog('grammarDialog')}
  function saveGrammar(event){event.preventDefault();const old=state.grammar.find(x=>x.id===$('#grammarId').value),point={id:old?.id||Store.newId('grammar'),pattern:$('#grammarPattern').value.trim(),explanation:$('#grammarExplanation').value.trim(),examples:$('#grammarExamples').value.trim(),level:old?.level||'',category:old?.category||'自定义',reviewed:old?.reviewed||false,reviewCount:old?.reviewCount||0,lastReviewedAt:old?.lastReviewedAt||null,wrongCount:old?.wrongCount||0,nextReviewAt:old?.nextReviewAt||null,userEdited:true};state.grammar=old?state.grammar.map(x=>x.id===old.id?point:x):[point,...state.grammar];closeDialog('grammarDialog');save()}
  function grammarAction(action,id,checked){const point=state.grammar.find(x=>x.id===id);if(!point)return;if(action==='edit')return openGrammar(id);if(action==='delete'){if(confirm(`确定删除“${point.pattern}”吗？`)){state.grammar=state.grammar.filter(x=>x.id!==id);save()}return}if(action==='review'){point.reviewed=checked;if(checked){point.lastReviewedAt=new Date().toISOString();point.reviewCount++;recordActivity('grammar')}save()}}
  function dueGrammarPoints(){const now=new Date();return state.grammar.filter(item=>item.nextReviewAt&&new Date(item.nextReviewAt)<=now)}
  function grammarQuizPools(){const all=state.grammar.filter(item=>item.pattern&&item.explanation),due=dueGrammarPoints(),wrong=all.filter(item=>item.wrongCount>0);return {all,due,wrong}}
  function updateGrammarQuizScope(){const pools=grammarQuizPools(),scope=$('#grammarQuizScope').value,count=pools[scope].length;$('#grammarQuizScopeHint').textContent=`今日到期 ${pools.due.length} 个 · 答错语法 ${pools.wrong.length} 个 · 当前范围 ${count} 个`;$('#startGrammarQuiz').disabled=count===0}
  function openGrammarQuiz(){grammarQuiz=null;const pools=grammarQuizPools();$('#grammarQuizScope').value=pools.due.length?'due':pools.wrong.length?'wrong':'all';$('#grammarQuizSetup').hidden=false;$('#grammarQuizSession').hidden=true;$('#grammarQuizResult').hidden=true;updateGrammarQuizScope();openDialog('grammarQuizDialog')}
  function startGrammarQuiz(){const pools=grammarQuizPools(),scope=$('#grammarQuizScope').value,pool=shuffle(pools[scope]);if(!pool.length)return toast('当前范围没有可测验的语法。');const buildQuestion=(point,index)=>{const direction=index%2?'meaning-pattern':'pattern-meaning',answerOf=item=>direction==='meaning-pattern'?item.pattern:item.explanation,prompt=direction==='meaning-pattern'?point.explanation:point.pattern,answer=answerOf(point),choices=[...new Set(pools.all.map(answerOf).filter(Boolean))],distractors=choices.filter(value=>value!==answer);if(distractors.length<3)return null;return {grammarId:point.id,direction,prompt,answer,options:shuffle([answer,...shuffle(distractors).slice(0,3)])}};const questions=[];pool.forEach(point=>{if(questions.length>=10)return;const question=buildQuestion(point,questions.length);if(question)questions.push(question)});if(!questions.length)return toast('当前范围至少需要 4 个不同答案才能开始语法测验。');grammarQuiz={questions,index:0,correct:0,answered:false,scope};$('#grammarQuizSetup').hidden=true;$('#grammarQuizResult').hidden=true;$('#grammarQuizSession').hidden=false;renderGrammarQuiz()}
  function renderGrammarQuiz(){const question=grammarQuiz?.questions[grammarQuiz.index];if(!question)return;$('#grammarQuizCounter').textContent=`${grammarQuiz.index+1} / ${grammarQuiz.questions.length}`;$('#grammarQuizScore').textContent=`${grammarQuiz.correct} 分`;$('#grammarQuizBar').style.width=`${grammarQuiz.index/grammarQuiz.questions.length*100}%`;$('#grammarQuizPrompt').textContent=question.prompt;$('#grammarQuizOptions').innerHTML=question.options.map(option=>`<button class="quiz-option" data-grammar-answer="${esc(option)}">${esc(option)}</button>`).join('');$('#grammarQuizFeedback').textContent='';$('#grammarQuizNext').hidden=true;grammarQuiz.answered=false}
  function answerGrammarQuiz(answer,button){if(!grammarQuiz||grammarQuiz.answered)return;grammarQuiz.answered=true;const question=grammarQuiz.questions[grammarQuiz.index],point=state.grammar.find(item=>item.id===question.grammarId),correct=answer===question.answer,now=new Date();if(correct)grammarQuiz.correct++;point.reviewCount++;point.lastReviewedAt=now.toISOString();point.reviewed=correct;point.wrongCount=correct?Math.max(0,(point.wrongCount||0)-1):(point.wrongCount||0)+1;point.nextReviewAt=new Date(now.getTime()+(correct?7:1)*86400000).toISOString();state.grammarAttempts.push({id:Store.newId('grammar-attempt'),grammarId:point.id,correct,direction:question.direction,date:now.toISOString()});recordActivity('grammar');$$('#grammarQuizOptions .quiz-option').forEach(option=>{option.disabled=true;if(option.dataset.grammarAnswer===question.answer)option.classList.add('correct')});if(!correct)button.classList.add('wrong');$('#grammarQuizFeedback').innerHTML=`<strong>${correct?'回答正确':`正确答案：${esc(question.answer)}`}</strong><small>${esc(point.examples||point.explanation)}</small>`;$('#grammarQuizNext').hidden=false;$('#grammarQuizNext').textContent=grammarQuiz.index===grammarQuiz.questions.length-1?'查看成绩':'下一题';save(false)}
  function nextGrammarQuiz(){if(!grammarQuiz?.answered)return;if(grammarQuiz.index>=grammarQuiz.questions.length-1){const total=grammarQuiz.questions.length,accuracy=Math.round(grammarQuiz.correct/total*100);$('#grammarQuizSession').hidden=true;$('#grammarQuizResult').hidden=false;$('#grammarQuizResultScore').textContent=`${grammarQuiz.correct} / ${total}`;$('#grammarQuizResultText').textContent=`正确率 ${accuracy}% · 答错项目已安排明日复习`;renderGrammar();renderProgress();return}grammarQuiz.index++;renderGrammarQuiz()}

  const writingPromptList=()=>Data.writingPrompts||[];
  const fullMockWriting=()=>state.activeFullMock?.phase==='writing';
  function currentWritingPrompt(){return writingPromptList().find(item=>item.id===$('#writingPromptSelect').value)||writingPromptList().find(item=>item.type===$('#writingTaskType').value)||writingPromptList()[0]}
  function loadWritingDraft(){const prompt=currentWritingPrompt();if(!prompt)return;activeWritingPromptId=prompt.id;const drafts=fullMockWriting()?(state.activeFullMock.writingDrafts||{}):(state.writingDrafts||{}),legacy=!fullMockWriting()&&!Object.keys(drafts).length?state.writingDraft:'';$('#writingText').value=drafts[prompt.id]??legacy??'';updateWritingCount()}
  function writingLength(){return Array.from($('#writingText').value).length}
  function updateWritingCount(){const prompt=currentWritingPrompt(),count=writingLength();$('#writingCount').textContent=`${count} 字`;$('#writingCount').className=count&&prompt&&(count<prompt.minChars||count>prompt.maxChars)?'wrong-text':'';renderEssayGuide()}
  function essayPromptItems(prompt){return (prompt?.prompt.match(/[①②③][^①②③]+/g)||[]).map(item=>item.replace(/^[①②③]\s*/,'').trim())}
  function essayStatus(count){if(!count)return ['尚未开始','先用 3 分钟写提纲，再动笔。','neutral'];if(count<520)return ['偏短',`还差约 ${600-count} 字，优先补例子和对策。`,'warn'];if(count<600)return ['接近目标',`还差约 ${600-count} 字，补一句理由或例子即可。`,'warn'];if(count<=700)return ['字数合适','保持结构清楚，最后检查连接词和终结语尾。','ok'];return ['偏长',`超出约 ${count-700} 字，删掉重复例子和口语化说明。`,'warn']}
  function renderEssayGuide(){const panel=$('#essayGuidePanel'),button=$('#openEssayGuideButton');if(!panel||!button)return;const prompt=currentWritingPrompt(),isEssay=prompt?.type==='54';button.hidden=!isEssay;panel.hidden=!isEssay;if(!isEssay)return;const text=$('#writingText').value.trim(),count=writingLength(),paragraphs=text?text.split(/\n+/).map(item=>item.trim()).filter(Boolean).length:0,connectors=['먼저','또한','반면','그러나','따라서','결론적으로','이를 위해','예를 들어'],used=connectors.filter(word=>text.includes(word)),[status,advice,statusClass]=essayStatus(count),items=essayPromptItems(prompt),topicItems=items.length?items:['题目通常要求回答原因、影响/问题、对策或个人观点。'];$('#essayGuideContent').innerHTML=`<div class="essay-status-grid"><article class="${statusClass}"><span>字数状态</span><strong>${status}</strong><small>${esc(advice)}</small></article><article><span>段落数</span><strong>${paragraphs || 0}</strong><small>建议 4 段：引入 / 论点1 / 论点2+对策 / 结论</small></article><article><span>连接表达</span><strong>${used.length} / ${connectors.length}</strong><small>${used.length?`已使用：${esc(used.join('、'))}`:'建议加入 먼저、또한、그러나、따라서 等。'}</small></article></div><div class="essay-guide-grid"><article><h3>1. 审题必须回答</h3><ol>${topicItems.map(item=>`<li>${esc(item)}</li>`).join('')}</ol></article><article><h3>2. 推荐段落分配</h3><ol><li>引言 80～100字：提出社会背景和立场。</li><li>本论1 160～180字：回答第一个问题，写原因或优点。</li><li>本论2 220～260字：写问题/影响，再接对策。</li><li>结论 80～120字：总结观点，提出个人与社会行动。</li></ol></article><article><h3>3. 可直接使用的韩语表达</h3><p lang="ko">최근 …에 대한 관심이 높아지고 있다.<br>이러한 현상은 …다는 점에서 의미가 있다.<br>반면에 …라는 문제도 나타날 수 있다.<br>이를 해결하기 위해서는 개인과 사회가 함께 노력해야 한다.<br>결론적으로 …는 방향으로 나아가야 한다.</p></article><article><h3>4. 交卷前检查</h3><ul><li>三个小问题是否都回答了。</li><li>每段第一句是否能看出中心。</li><li>是否使用正式书面语：-다, -ㄴ다, -아/어야 한다。</li><li>是否避免“我觉得、特别、真的”等口语化表达。</li><li>助词、时态、连接词是否统一。</li></ul></article></div>`}
  function insertEssaySkeleton(){const prompt=currentWritingPrompt();if(prompt?.type!=='54')return toast('大作文骨架只适用于第54题。');const box=$('#writingText'),hasContent=box.value.trim().length>0;if(hasContent&&!confirm('当前草稿已有内容，是否用大作文骨架替换？'))return;box.value=`최근 ${prompt.title}에 대한 관심이 높아지고 있다. 이는 개인의 생활뿐만 아니라 사회 전체에도 영향을 미치는 중요한 문제이다. 나는 이 문제를 균형 있게 바라보고 적절한 대책을 마련해야 한다고 생각한다.\n\n먼저, 이 현상이 나타나는 가장 큰 이유는 __________________________________ 때문이다. 예를 들어, __________________________________. 이러한 점에서 __________________________________다고 볼 수 있다.\n\n또한, 이 문제는 __________________________________라는 영향을 가져올 수 있다. 반면에 긍정적인 측면도 있으므로 무조건 부정적으로만 볼 수는 없다. 따라서 이를 해결하기 위해서는 개인은 __________________________________해야 하고, 사회는 __________________________________할 필요가 있다.\n\n결론적으로, ${prompt.title} 문제는 단순히 한 사람의 노력만으로 해결되기 어렵다. 앞으로 개인과 사회가 함께 노력한다면 보다 바람직한 방향으로 나아갈 수 있을 것이다.`;writingVersionOf='';saveDraft();updateWritingCount();toast('已插入第54题大作文骨架，请替换下划线部分。');box.focus()}
  function updateWritingTimer(){const minutes=Math.floor(writingSeconds/60),seconds=writingSeconds%60;$('#writingTimer').textContent=`${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`;$('#writingTimer').classList.toggle('urgent',writingSeconds<=300)}
  function syncWritingTimer(){if(fullMockWriting()){state.activeFullMock.writingRemainingSeconds=writingSeconds;state.activeFullMock.updatedAt=new Date().toISOString()}}
  function stopWritingTimer(){const hadTimer=!!writingTimerId;if(writingTimerId){clearInterval(writingTimerId);writingTimerId=null}if(hadTimer||writingSeconds>0)syncWritingTimer();$('#writingTimerButton').textContent=writingSeconds>0?'继续计时':'开始计时'}
  function resetWritingTimer(force=false){stopWritingTimer();const fullMock=fullMockWriting();if(fullMock)writingSeconds=force?3000:(state.activeFullMock.writingRemainingSeconds??3000);else writingSeconds=(currentWritingPrompt()?.minutes||30)*60;syncWritingTimer();updateWritingTimer();$('#writingTimerButton').textContent='开始计时';if(fullMock)save(false)}
  function toggleWritingTimer(){if(writingTimerId){stopWritingTimer();save(false);return}if(writingSeconds<=0)resetWritingTimer();$('#writingTimerButton').textContent='暂停';writingTimerId=setInterval(()=>{writingSeconds=Math.max(0,writingSeconds-1);syncWritingTimer();updateWritingTimer();if(fullMockWriting()&&writingSeconds%15===0)save(false);if(writingSeconds===0){stopWritingTimer();save(false);toast('写作时间到，请保存或提交评分。')}},1000)}
  function updateWritingPrompt(){const prompt=currentWritingPrompt();if(!prompt)return;const mock=state.activeFullMock,scores=mock?.writingTaskScores||{},completed=Object.keys(scores).length,mockText=fullMockWriting()?` · 全科模考已评分 ${completed}/4 题`:'';$('#writingTaskBadge').textContent=fullMockWriting()?'全科模考 · 写作':`第 ${prompt.type} 题 · ${prompt.points} 分`;$('#writingPromptTitle').textContent=prompt.title;$('#writingPrompt').textContent=prompt.prompt;$('#writingGuide').textContent=prompt.guide;$('#writingTarget').textContent=`目标 ${prompt.minChars}～${prompt.maxChars} 字 · 建议 ${prompt.minutes} 分钟 · 草稿自动保存${mockText}`;const latest=[...state.writings].reverse().find(item=>item.promptId===prompt.id&&item.revisedText);$('#loadLatestRevision').hidden=!latest;updateWritingCount()}
  function renderWritingPrompts(preferredId=''){const type=$('#writingTaskType').value||'54',prompts=writingPromptList().filter(item=>item.type===type),current=preferredId||$('#writingPromptSelect').value;$('#writingPromptSelect').innerHTML=prompts.map(item=>`<option value="${esc(item.id)}">${esc(item.title)}</option>`).join('');if(prompts.some(item=>item.id===current))$('#writingPromptSelect').value=current;updateWritingPrompt();loadWritingDraft();resetWritingTimer()}
  function writingScoreDisplay(item){if(item.score===null)return '';const actual=Math.round(item.score*(item.maxScore||100)/100);return `${actual}/${item.maxScore||100} 分 · 综合 ${item.score}/100`}
  function applyWritingScoreToMock(item){const mock=state.activeFullMock;if(!mock||!item?.fullMockId||mock.id!==item.fullMockId||!['51','52','53','54'].includes(item.taskType)||item.score===null)return;mock.writingTaskScores=mock.writingTaskScores||{};mock.writingTaskScores[item.taskType]=Math.round(item.score*(item.maxScore||100)/100);const types=['51','52','53','54'];if(types.every(type=>mock.writingTaskScores[type]!==undefined))mock.writingScore=types.reduce((sum,type)=>sum+mock.writingTaskScores[type],0);mock.updatedAt=new Date().toISOString();const finished=finalizeFullMock(mock);save(false);if(finished)toast(`全科模考已完成：${finished.totalScore} / 300 · ${fullMockLevel(finished.totalScore)}`)}
  function renderWritingFeedback(item){if(!item?.rubric){$('#feedback').hidden=true;return}applyWritingScoreToMock(item);$('#feedback').hidden=false;$('#writingScore').textContent=writingScoreDisplay(item);const labels={content:'内容完成',structure:'结构逻辑',language:'语法词汇',style:'书面文体'};$('#writingRubric').innerHTML=Object.entries(labels).map(([key,label])=>`<article><span>${label}</span><strong>${item.rubric[key]} / 25</strong></article>`).join('');$('#writingSummary').textContent=item.summary||'';$('#writingErrorList').innerHTML=item.errors.length?item.errors.map(error=>`<article class="writing-error-item"><small>${esc(error.category)}</small><strong>${esc(error.original)} → ${esc(error.correction)}</strong><span>${esc(error.explanation)}</span></article>`).join(''):'<div class="empty">本次没有识别到明确错误。</div>';$('#writingRevision').textContent=item.revisedText||item.text;$('#writingNextFocus').textContent=item.nextFocus?`下一步重点：${item.nextFocus}`:''}
  function renderWritingErrors(){const errors=state.writings.flatMap(item=>item.errors||[]),counts=new Map();errors.forEach(error=>counts.set(error.category,(counts.get(error.category)||0)+1));const sorted=[...counts.entries()].sort((a,b)=>b[1]-a[1]);$('#writingErrors').innerHTML=errors.length?`<div class="section-heading"><div><span class="eyebrow">ERROR PROFILE</span><h2>写作错误档案</h2></div><span class="muted">累计 ${errors.length} 处</span></div><div class="writing-error-summary">${sorted.map(([category,count])=>`<span>${esc(category)} ${count}</span>`).join('')}</div>`:''}
  function renderWriting(){if(!$('#writingPromptSelect').options.length)renderWritingPrompts();else updateWritingPrompt();const history=state.writings.slice().reverse();$('#writingHistory').innerHTML=history.length?`<div class="section-heading"><div><span class="eyebrow">HISTORY</span><h2>写作记录</h2></div><span class="muted">${history.length} 次</span></div><div class="history-list">${history.map(item=>`<details class="history-item"><summary><span>第 ${esc(item.taskType==='free'?'自由':item.taskType)} 题 · ${esc(item.promptTitle||item.text.slice(0,35))}</span>${item.score!==null?` <span class="history-score">${writingScoreDisplay(item)}</span>`:''}</summary><p class="muted">${formatFullDate(item.date)} · ${item.characterCount} 字${item.versionOf?' · 改写练习':''}</p><p lang="ko">${esc(item.text)}</p>${item.summary?`<p>${esc(item.summary)}</p>`:''}${item.revisedText?`<div class="revision-panel"><strong>修订版</strong><p lang="ko">${esc(item.revisedText)}</p><button class="secondary" data-writing-rewrite="${esc(item.id)}">载入修订版继续改写</button></div>`:''}${item.feedback&&!item.rubric?`<pre>${esc(item.feedback)}</pre>`:''}</details>`).join('')}</div>`:'';renderWritingErrors()}
  function rotatePrompt(){const select=$('#writingPromptSelect'),count=select.options.length;if(!count)return;saveDraft();select.selectedIndex=(select.selectedIndex+1)%count;writingVersionOf='';updateWritingPrompt();loadWritingDraft();resetWritingTimer()}
  function loadWritingRevision(id=''){const prompt=currentWritingPrompt(),item=id?state.writings.find(entry=>entry.id===id):[...state.writings].reverse().find(entry=>entry.promptId===prompt?.id&&entry.revisedText);if(!item?.revisedText)return;saveDraft();const target=writingPromptList().find(entry=>entry.id===item.promptId);if(target){$('#writingTaskType').value=target.type;renderWritingPrompts(target.id)}$('#writingText').value=item.revisedText;writingVersionOf=item.id;saveDraft();updateWritingCount();window.scrollTo({top:0,behavior:'smooth'});toast('已载入修订版，可进行第二次写作。')}
  function saveDraft(){const content=$('#writingText').value,promptId=activeWritingPromptId||currentWritingPrompt()?.id;if(!promptId)return;if(fullMockWriting()){state.activeFullMock.writingDrafts=state.activeFullMock.writingDrafts||{};state.activeFullMock.writingDrafts[promptId]=content;syncWritingTimer()}else{state.writingDrafts=state.writingDrafts||{};state.writingDrafts[promptId]=content;state.writingDraft=content}if(!Store.saveDraft(content)||!save(false))toast('草稿保存失败，请导出备份。')}
