  async function prepareImport(event){const file=event.target.files?.[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('备份文件超过 10 MB');const parsed=JSON.parse(await file.text()),data=Store.parseBackup(parsed),counts=Store.counts(data);pendingImport={fileName:file.name,data};$('#importFileName').textContent=file.name;$('#importSummary').innerHTML=`<strong>备份内容</strong><br>单词 ${counts.words} 个 · 语法 ${counts.grammar} 个 · 写作 ${counts.writings} 次 · 词汇测验 ${counts.quizzes} 次 · 题库 ${counts.questions} 题 · 在线练习 ${counts.practices} 次 · 错题 ${counts.wrong} 道 · 真题记录 ${counts.tests} 条`;openDialog('importDialog')}catch(error){event.target.value='';pendingImport=null;toast(`无法导入：${error.message}`)}}
